{
  "name": "opencode-graph-live",
  "version": "0.1.2",
  "description": "Live file-activity graph for opencode sidebar (which files the agent is reading / modifying)",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/4m1z/opencode-graph-live"
  },
  "homepage": "https://github.com/4m1z/opencode-graph-live#readme",
  "keywords": ["opencode", "opencode-plugin", "tui", "sidebar", "file-graph"],
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist/",
    "src/",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "bun build ./src/index.ts --outdir ./dist --target bun && bun build ./src/tui.tsx --outdir ./dist --target bun --external @opencode/plugin --external '@opencode/plugin/*' --external '@opentui/*' --external solid-js",
    "prepack": "bun run build",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.8",
    "@opentui/solid": ">=0.5.8",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "typescript": "^5.9.0"
  }
}
